insert into public.signals (external_key, date, asset_class, kind, headline, summary, entities, company_ids, source_name, source_url, source)
  values ('footballbenchmark.com/w/private-equity-s-expanding-footprint-in-football-risks-rewards-and-the-future', null, 'sports', 'performance', 'Real Madrid reaches a record €7.7bn enterprise value in Football Benchmark''s 2026 club valuation ranking', 'Multi-club owners hold stakes in nearly 48% of Big Five clubs in 2025-26, up from 41.7%.', array['Real Madrid']::text[], (select coalesce(array_agg(id), '{}'::uuid[]) from public.companies where lower(name) = any(array['real madrid']::text[])), 'Football Benchmark', 'https://footballbenchmark.com/w/private-equity-s-expanding-footprint-in-football-risks-rewards-and-the-future', 'web_research')
